  public int pop(){
    if (topo == null)
      return -1;
    No lixo = topo;
    topo = topo.prox;
    lixo.prox = null;
    return lixo.dado;
  }

  public int top(){
    if (topo == null)
      return -1;
    return (topo.dado);
  }
}
```

